      texts: [
      { name: "title", x: 107.5, y: 78, w: 494.9, h: 150, rotate: 0, font: "Caveat", size: 138, weight: 700, italic: false, colour: "#f3f1e7", opacity: 1, letterSpacing: 0, lineHeight: 1.087, align: "left", valign: "top", shadow: "rgba(255, 255, 255, 0.35) 0px 0px 6px", charW: 0.398, maxChars: 13, sample: msg("Key Words") },
      { name: "text2", x: 119.5, y: 222, w: 626.4, h: 54, rotate: 0, font: "Urbanist", size: 42, weight: 400, italic: false, colour: "#c9cfc4", opacity: 1, letterSpacing: 0, lineHeight: 1.286, align: "left", valign: "top", charW: 0.451, maxChars: 47, sample: msg("Copy these into your science book") },
      { name: "text3", x: 1445.5, y: 111, w: 275.1, h: 60, rotate: 0, font: "Caveat", size: 51, weight: 700, italic: false, colour: "#f6e38a", opacity: 1, letterSpacing: 0, lineHeight: 1.176, align: "left", valign: "top", charW: 0.358, maxChars: 21, sample: msg("Say them aloud!") },
      { name: "text4", x: 133.4, y: 631.1, w: 288.3, h: 78, rotate: -3, font: "Caveat", size: 69, weight: 700, italic: false, colour: "#f4abc4", opacity: 1, letterSpacing: 0, lineHeight: 1.13, align: "left", valign: "top", charW: 0.378, maxChars: 16, sample: msg("Evaporation") },
      { name: "text5", x: 139.8, y: 719.8, w: 331, h: 144, rotate: -3, font: "Urbanist", size: 36, weight: 400, italic: false, colour: "#f3f1e7", opacity: 1, letterSpacing: 0, lineHeight: 1.333, align: "left", valign: "top", charW: 0.449, maxChars: 70, sample: msg("Water warms up and turns into a gas called vapour.") },
      { name: "text6", x: 574.2, y: 629.8, w: 319.1, h: 78, rotate: 2, font: "Caveat", size: 69, weight: 700, italic: false, colour: "#f3f1e7", opacity: 1, letterSpacing: 0, lineHeight: 1.13, align: "left", valign: "top", charW: 0.384, maxChars: 17, sample: msg("Condensation") },
      { name: "text7", x: 569.9, y: 719.9, w: 331, h: 144, rotate: 2, font: "Urbanist", size: 36, weight: 400, italic: false, colour: "#f3f1e7", opacity: 1, letterSpacing: 0, lineHeight: 1.333, align: "left", valign: "top", charW: 0.443, maxChars: 69, sample: msg("Vapour cools down and turns back into tiny drops.") },
      { name: "text8", x: 1020.4, y: 630.3, w: 305.8, h: 78, rotate: -1.5, font: "Caveat", size: 69, weight: 700, italic: false, colour: "#9fd3ee", opacity: 1, letterSpacing: 0, lineHeight: 1.13, align: "left", valign: "top", charW: 0.34, maxChars: 19, sample: msg("Precipitation") },
      { name: "text9", x: 1023.7, y: 719.9, w: 331, h: 144, rotate: -1.5, font: "Urbanist", size: 36, weight: 400, italic: false, colour: "#f3f1e7", opacity: 1, letterSpacing: 0, lineHeight: 1.333, align: "left", valign: "top", charW: 0.403, maxChars: 75, sample: msg("Water falls from clouds as rain, sleet, hail or snow.") },
      { name: "text10", x: 1462, y: 627.7, w: 225.9, h: 78, rotate: 2.5, font: "Caveat", size: 69, weight: 700, italic: false, colour: "#f6e38a", opacity: 1, letterSpacing: 0, lineHeight: 1.13, align: "left", valign: "top", charW: 0.326, maxChars: 14, sample: msg("Collection") },
      { name: "text11", x: 1456.6, y: 719.8, w: 331, h: 144, rotate: 2.5, font: "Urbanist", size: 36, weight: 400, italic: false, colour: "#f3f1e7", opacity: 1, letterSpacing: 0, lineHeight: 1.333, align: "left", valign: "top", charW: 0.423, maxChars: 69, sample: msg("Water gathers in seas, rivers, lakes and puddles.") }
      ]
